// n8n Code node: Rank Research Pages V1
// Mode: Run Once for All Items
//
// Deterministically ranks crawled pages for downstream LLM extraction.
// Selects up to 5 pages per account.

const MAX_PAGES_PER_ACCOUNT = 5;

const POSITIVE_TERMS = [
  "commercial",
  "janitorial",
  "office",
  "facility",
  "facilities",
  "service",
  "services",
  "industry",
  "industries",
  "about",
  "quote",
  "estimate",
  "contact"
];

const NEGATIVE_TERMS = [
  "blog",
  "news",
  "privacy",
  "terms",
  "career",
  "careers",
  "login",
  "signup",
  "cart",
  "shop"
];

function scorePage(r) {
  const url = String(r.source_url || "").toLowerCase();
  const title = String(r.page_title || "").toLowerCase();
  const combined = `${url} ${title}`;

  let score = 0;

  if (r.page_depth === 0) score += 8;

  for (const term of POSITIVE_TERMS) {
    if (combined.includes(term)) score += 3;
  }

  for (const term of NEGATIVE_TERMS) {
    if (combined.includes(term)) score -= 8;
  }

  const chars = Math.max(
    Number(r.text_original_chars || 0),
    Number(r.markdown_original_chars || 0)
  );

  if (chars >= 500) score += 2;
  if (chars >= 1500) score += 2;

  return score;
}

const matched = items
  .map((item) => item.json)
  .filter((r) => r.account_match_status === "matched" && r.account_id);

const groups = new Map();

for (const r of matched) {
  r.page_relevance_score = scorePage(r);

  if (!groups.has(r.account_id)) {
    groups.set(r.account_id, []);
  }

  groups.get(r.account_id).push(r);
}

const output = [];

for (const [accountId, rows] of groups.entries()) {
  rows.sort((a, b) => {
    if (b.page_relevance_score !== a.page_relevance_score) {
      return b.page_relevance_score - a.page_relevance_score;
    }

    const ad = a.page_depth ?? 999;
    const bd = b.page_depth ?? 999;
    return ad - bd;
  });

  for (const r of rows.slice(0, MAX_PAGES_PER_ACCOUNT)) {
    output.push({
      json: {
        ...r,
        selected_for_research: true
      }
    });
  }
}

return output;

// n8n Code node: Map Crawled Pages to Accounts V1.1
// Mode: Run Once for All Items
//
// Compatible with the balanced per-account crawl architecture.
// Gets the account lookup from Fetch Pilot Accounts rather than the old
// single-config builder node.

const accounts = $("Fetch Pilot Accounts")
  .all()
  .map(i => ({
    id: i.json.id,
    company_name: i.json.company_name,
    website_url: i.json.website_url,
    normalized_domain: i.json.normalized_domain
  }));

const MAX_CONTENT_CHARS = 30000;

function clean(v) {
  if (v === undefined || v === null) return null;
  const s = String(v).trim();
  return s === "" ? null : s;
}

function normalizeHostname(value) {
  const raw = clean(value);
  if (!raw) return null;

  try {
    const candidate = /^[a-z][a-z0-9+.-]*:\/\//i.test(raw)
      ? raw
      : `https://${raw}`;

    return new URL(candidate).hostname
      .toLowerCase()
      .replace(/^www\./, "")
      .replace(/\.$/, "");
  } catch {
    let s = raw
      .toLowerCase()
      .replace(/^[a-z][a-z0-9+.-]*:\/\//i, "")
      .replace(/^\/\//, "")
      .split(/[/?#]/)[0]
      .replace(/:\d+$/, "")
      .replace(/^www\./, "")
      .replace(/\.$/, "");

    return s || null;
  }
}

function pageUrl(p) {
  return clean(
    p?.crawl?.loadedUrl ??
    p?.loadedUrl ??
    p?.url
  );
}

function pageDepth(p) {
  const raw = p?.crawl?.depth ?? p?.depth;
  if (raw === undefined || raw === null || raw === "") return null;

  const n = Number(raw);
  return Number.isFinite(n) ? n : null;
}

function observedAt(p) {
  return clean(
    p?.crawl?.loadedTime ??
    p?.loadedTime ??
    p?.fetchedAt ??
    p?.crawledAt
  ) || new Date().toISOString();
}

function titleOf(p) {
  return clean(
    p?.metadata?.title ??
    p?.title
  );
}

function cap(text) {
  const value = clean(text);

  if (!value) {
    return {
      value: null,
      truncated: false,
      original_chars: 0
    };
  }

  return {
    value: value.slice(0, MAX_CONTENT_CHARS),
    truncated: value.length > MAX_CONTENT_CHARS,
    original_chars: value.length
  };
}

let pages = [];

for (const item of items) {
  const value = item.json;

  if (Array.isArray(value)) {
    pages.push(...value);
  } else if (Array.isArray(value?.data)) {
    pages.push(...value.data);
  } else {
    pages.push(value);
  }
}

return pages.map((p) => {
  const sourceUrl = pageUrl(p);
  const host = normalizeHostname(sourceUrl);

  const account = accounts.find((a) => {
    const domain = normalizeHostname(a.normalized_domain);

    if (!domain || !host) return false;

    return host === domain || host.endsWith(`.${domain}`);
  }) || null;

  const textCap = cap(p?.text);
  const markdownCap = cap(p?.markdown);

  return {
    json: {
      research_version: "WI-V1A.2.0",

      account_match_status: account ? "matched" : "unmatched",
      account_id: account?.id ?? null,
      company_name: account?.company_name ?? null,
      normalized_domain: account?.normalized_domain ?? null,

      source_url: sourceUrl,
      source_hostname: host,

      source_type: "website",
      source_provider: "apify_website_content_crawler",
      source_observed_at: observedAt(p),

      page_title: titleOf(p),
      page_depth: pageDepth(p),

      content_text: textCap.value,
      content_markdown: markdownCap.value,

      content_truncated:
        textCap.truncated || markdownCap.truncated,

      text_original_chars: textCap.original_chars,
      markdown_original_chars: markdownCap.original_chars,

      crawl_metadata: {
        url: clean(p?.url),
        loaded_url: clean(p?.crawl?.loadedUrl ?? p?.loadedUrl),
        canonical_url: clean(
          p?.metadata?.canonicalUrl ??
          p?.canonicalUrl
        ),
        description: clean(
          p?.metadata?.description ??
          p?.description
        ),
        language_code: clean(
          p?.metadata?.languageCode ??
          p?.languageCode
        ),
        referrer_url: clean(
          p?.crawl?.referrerUrl ??
          p?.referrerUrl
        )
      }
    }
  };
});

// n8n Code node: Build Website Crawl Jobs V1.3
// Mode: Run Once for All Items
//
// Strategy:
// 1) Cheap/fast Cheerio crawl first.
// 2) Adaptive browser crawl only for accounts with insufficient content.
//
// Output: one crawl job per account.

const RESEARCH_VERSION = "WI-V1A.3.0";
const MAX_CRAWL_PAGES = 5;
const MAX_RESULTS = 5;

function clean(v) {
  if (v === undefined || v === null) return null;
  const s = String(v).trim();
  return s === "" ? null : s;
}

return items.map(({ json }) => {
  const id = clean(json.id);
  const companyName = clean(json.company_name);
  const websiteUrl = clean(json.website_url);
  const normalizedDomain = clean(json.normalized_domain);

  if (!id || !companyName || !websiteUrl || !normalizedDomain) {
    throw new Error(
      `Pilot account missing required fields: ${JSON.stringify(json)}`
    );
  }

  return {
    json: {
      research_version: RESEARCH_VERSION,

      account_id: id,
      company_name: companyName,
      normalized_domain: normalizedDomain,
      website_url: websiteUrl,

      actor_input: {
        startUrls: [{ url: websiteUrl }],

        // Raw HTTP first: substantially lighter/faster than browser crawling.
        crawlerType: "cheerio",

        maxCrawlDepth: 1,
        maxCrawlPages: MAX_CRAWL_PAGES,
        maxResults: MAX_RESULTS,

        initialConcurrency: 1,
        maxConcurrency: 1,

        useSitemaps: false,
        useLlmsTxt: false,
        respectRobotsTxtFile: true,

        proxyConfiguration: {
          useApifyProxy: true
        },

        blockMedia: true,
        saveMarkdown: true,
        saveHtml: false,
        saveHtmlAsFile: false,
        saveScreenshots: false,
        summarize: false
      }
    }
  };
});

// Build Company Research Packets V1.1
// Mode: Run Once for All Items

const RESEARCH_VERSION = "WI-V1B.0.0-GEMINI";

const MAX_PAGES_PER_ACCOUNT = 5;
const MAX_CHARS_PER_PAGE = 7000;
const MAX_PACKET_CHARS = 24000;

// Explicitly collect ALL ranked pages from the upstream node.
const rows = $("Rank Research Pages V1")
  .all()
  .map(i => i.json)
  .filter(r =>
    r.account_id &&
    r.company_name &&
    r.source_url
  );

const groups = new Map();

for (const row of rows) {
  if (!groups.has(row.account_id)) {
    groups.set(row.account_id, {
      account_id: row.account_id,
      company_name: row.company_name,
      normalized_domain: row.normalized_domain,
      pages: []
    });
  }

  groups.get(row.account_id).pages.push(row);
}

const output = [];

for (const group of groups.values()) {

  const seenUrls = new Set();

  const selected = group.pages
    .sort(
      (a, b) =>
        Number(b.page_relevance_score || 0) -
        Number(a.page_relevance_score || 0)
    )
    .filter(page => {
      if (seenUrls.has(page.source_url)) {
        return false;
      }

      seenUrls.add(page.source_url);
      return true;
    })
    .slice(0, MAX_PAGES_PER_ACCOUNT);

  let packetChars = 0;
  const documents = [];

  for (const page of selected) {

    if (packetChars >= MAX_PACKET_CHARS) {
      break;
    }

    const raw =
      String(
        page.content_markdown ||
        page.content_text ||
        ""
      ).trim();

    if (!raw) {
      continue;
    }

    const remaining =
      MAX_PACKET_CHARS - packetChars;

    const content = raw.slice(
      0,
      Math.min(
        MAX_CHARS_PER_PAGE,
        remaining
      )
    );

    if (!content) {
      continue;
    }

    packetChars += content.length;

    documents.push({
      source_url: page.source_url,

      source_observed_at:
        page.source_observed_at ||
        new Date().toISOString(),

      page_title:
        page.page_title || null,

      page_relevance_score:
        Number(
          page.page_relevance_score || 0
        ),

      content
    });
  }

  if (!documents.length) {
    continue;
  }

  output.push({
    json: {
      research_version: RESEARCH_VERSION,

      account_id:
        group.account_id,

      company_name:
        group.company_name,

      normalized_domain:
        group.normalized_domain,

      page_count:
        documents.length,

      packet_chars:
        packetChars,

      source_urls:
        documents.map(
          d => d.source_url
        ),

      documents
    }
  });
}

return output;

