function makeEvidenceSchema(values) {
  return {
    type: "object",

    properties: {
      value: {
        type: "string",
        enum: values
      },

      observed_text: {
        type: "string",
        description:
          "Short verbatim excerpt copied from supplied website content, approximately 20 words or fewer. Empty string when unknown."
      },

      source_url: {
        type: "string",
        description:
          "Exact URL from the supplied documents supporting the finding. Empty string when unknown."
      },

      confidence: {
        type: "integer",
        minimum: 0,
        maximum: 100,
        description:
          "Confidence from 0 to 100 based only on supplied website evidence."
      },

      reason: {
        type: "string",
        description:
          "Concise explanation grounded only in supplied website content."
      }
    },

    required: [
      "value",
      "observed_text",
      "source_url",
      "confidence",
      "reason"
    ],

    additionalProperties: false
  };
}

const evidenceProperties = {};

for (const key of Object.keys(specs)) {
  evidenceProperties[key] = makeEvidenceSchema(specs[key]);
}

