// --------------------------------------------------
// Helpers
// --------------------------------------------------

function decodeBasicEntities(value) {
  return String(value || "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&apos;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">");
}


function normalizeForQuoteMatch(value) {
  return decodeBasicEntities(value)

    // Markdown links: [text](url) -> text
    .replace(
      /\[([^\]]+)\]\([^\)]+\)/g,
      "$1"
    )

    // Strip HTML
    .replace(
      /<[^>]*>/g,
      " "
    )

    // Normalize quotation marks
    .replace(
      /[“”]/g,
      '"'
    )
    .replace(
      /[‘’]/g,
      "'"
    )

    // Strip common markdown syntax
    .replace(
      /[`*_~>#|]/g,
      " "
    )

    // Strip punctuation but keep words/numbers
    .replace(
      /[^\p{L}\p{N}'"\s-]/gu,
      " "
    )

    // Normalize dashes
    .replace(
      /[-–—]+/g,
      " "
    )

    .replace(
      /\s+/g,
      " "
    )

    .trim()
    .toLowerCase();
}


function quoteExistsInSource(
  sourceContent,
  observedText
) {
  const source =
    normalizeForQuoteMatch(
      sourceContent
    );

  const quote =
    normalizeForQuoteMatch(
      observedText
    );

  if (!source || !quote) {
    return false;
  }

  // Strongest check
  if (source.includes(quote)) {
    return true;
  }

  const quoteTokens =
    quote
      .split(" ")
      .filter(Boolean);

  const sourceTokens =
    source
      .split(" ")
      .filter(Boolean);

  if (
    quoteTokens.length < 4 ||
    sourceTokens.length <
      quoteTokens.length
  ) {
    return false;
  }

  /*
    Conservative fallback.

    For longer quotes allow one token mismatch.
    For shorter quotes require exact contiguous tokens.

    This helps with:
    - punctuation changes
    - markdown formatting
    - one minor crawler/model normalization difference
  */

  const allowedMismatches =
    quoteTokens.length >= 8
      ? 1
      : 0;

  for (
    let i = 0;
    i <=
      sourceTokens.length -
        quoteTokens.length;
    i++
  ) {
    let mismatches = 0;

    for (
      let j = 0;
      j < quoteTokens.length;
      j++
    ) {
      if (
        sourceTokens[i + j] !==
        quoteTokens[j]
      ) {
        mismatches++;

        if (
          mismatches >
          allowedMismatches
        ) {
          break;
        }
      }
    }

    if (
      mismatches <=
      allowedMismatches
    ) {
      return true;
    }
  }

  return false;
}


function extractGeminiText(response) {
  const candidates =
    response?.candidates;

  if (
    !Array.isArray(candidates) ||
    candidates.length === 0
  ) {
    throw new Error(
      "Gemini response contains no candidates."
    );
  }

  const candidate =
    candidates[0];

  const finishReason =
    candidate?.finishReason ||
    null;

  if (
    finishReason &&
    ![
      "STOP",
      "MAX_TOKENS"
    ].includes(finishReason)
  ) {
    throw new Error(
      `Gemini returned unexpected finishReason: ${finishReason}`
    );
  }

  const parts =
    candidate?.content?.parts;

  if (!Array.isArray(parts)) {
    throw new Error(
      "Gemini response contains no content.parts array."
    );
  }

  const textPart =
    parts.find(
      part =>
        typeof part?.text ===
          "string" &&
        part.text.trim()
    );

  if (!textPart) {
    throw new Error(
      "Gemini response contains no text output."
    );
  }

  return textPart.text.trim();
}


function conceptPresent(value) {
  if (value === "unknown") {
    return null;
  }

  if (value === "absent") {
    return false;
  }

  return true;
}


function downgradeToUnknown(
  original,
  issue
) {
  return {
    value: "unknown",

    sourceUrl: null,

    observedText: "",

    confidence: 0,

    reason:
      `Validation downgraded this field to unknown: ${issue}`,

    validationStatus:
      "downgraded_to_unknown",

    validationIssue:
      issue,

    originalValue:
      original.value || null,

    originalSourceUrl:
      original.sourceUrl || null,

    originalObservedText:
      original.observedText || "",

    originalReason:
      original.reason || ""
  };
}


// --------------------------------------------------
// Output structures
// --------------------------------------------------

const evidenceRows = [];

const accountSummaries = [];

const validationWarnings = [];


// --------------------------------------------------
// Process Gemini responses
// --------------------------------------------------

for (const item of items) {

  const response =
    item.json;

  const rawText =
    extractGeminiText(
      response
    );

  let parsed;

  try {
    parsed =
      JSON.parse(
        rawText
      );
  } catch (error) {
    throw new Error(
      `Gemini output is not valid JSON: ${error.message}`
    );
  }


  // ------------------------------------------------
  // Account identity
  // ------------------------------------------------

  if (!parsed.account_id) {
    throw new Error(
      "Gemini response missing account_id."
    );
  }

  const packet =
    packetByAccount.get(
      parsed.account_id
    );

  if (!packet) {
    throw new Error(
      `Gemini returned unknown account_id: ${parsed.account_id}`
    );
  }

  if (
    parsed.company_name !==
    packet.company_name
  ) {
    throw new Error(
      `Company-name mismatch for ${parsed.account_id}. ` +
      `Expected '${packet.company_name}', ` +
      `got '${parsed.company_name}'.`
    );
  }


  // ------------------------------------------------
  // Build source-document lookup
  // ------------------------------------------------

  const documents =
    Array.isArray(
      packet.documents
    )
      ? packet.documents
      : [];

  const sourceDocumentMap =
    new Map();

  for (const doc of documents) {

    if (!doc.source_url) {
      continue;
    }

    sourceDocumentMap.set(
      doc.source_url,
      doc
    );
  }


  // ------------------------------------------------
  // Evidence object
  // ------------------------------------------------

  const evidence =
    parsed.evidence;

  if (
    !evidence ||
    typeof evidence !== "object"
  ) {
    throw new Error(
      `Missing evidence object for ${packet.company_name}.`
    );
  }


  let downgradedFields = 0;


  // ------------------------------------------------
  // Validate all evidence dimensions
  // ------------------------------------------------

  for (
    const [
      key,
      allowedValues
    ]
    of Object.entries(
      valueDomains
    )
  ) {

    const e =
      evidence[key];

    if (!e) {
      throw new Error(
        `Missing evidence key '${key}' for ${packet.company_name}.`
      );
    }


    // ----------------------------------------------
    // Validate value
    // ----------------------------------------------

    const rawValue =
      String(
        e.value || ""
      ).trim();

    if (
      !allowedValues.has(
        rawValue
      )
    ) {
      throw new Error(
        `Invalid value '${rawValue}' for '${key}' / ${packet.company_name}.`
      );
    }


    // ----------------------------------------------
    // Validate confidence
    // ----------------------------------------------

    const rawConfidence =
      Number(
        e.confidence
      );

    if (
      !Number.isInteger(
        rawConfidence
      ) ||
      rawConfidence < 0 ||
      rawConfidence > 100
    ) {
      throw new Error(
        `Invalid confidence '${e.confidence}' for '${key}' / ${packet.company_name}.`
      );
    }


    // ----------------------------------------------
    // Normalize raw model fields
    // ----------------------------------------------

    const rawSourceUrl =
      typeof e.source_url ===
        "string" &&
      e.source_url.trim()
        ? e.source_url.trim()
        : null;

    const rawObservedText =
      typeof e.observed_text ===
        "string"
        ? e.observed_text.trim()
        : "";

    const rawReason =
      typeof e.reason ===
        "string"
        ? e.reason.trim()
        : "";

    if (!rawReason) {
      throw new Error(
        `Missing reason for '${key}' / ${packet.company_name}.`
      );
    }


    // ----------------------------------------------
    // Start with model output
    // ----------------------------------------------

    let normalized = {
      value:
        rawValue,

      sourceUrl:
        rawSourceUrl,

      observedText:
        rawObservedText,

      confidence:
        rawConfidence,

      reason:
        rawReason,

      validationStatus:
        "validated",

      validationIssue:
        null,

      originalValue:
        null,

      originalSourceUrl:
        null,

      originalObservedText:
        null,

      originalReason:
        null
    };


    // ----------------------------------------------
    // Unknown evidence
    // ----------------------------------------------

    if (
      rawValue ===
      "unknown"
    ) {

      /*
        Unknown is safe.

        Remove any accidental
        source assertion Gemini
        may have attached.
      */

      normalized.sourceUrl =
        null;

      normalized.observedText =
        "";

    } else {

      // --------------------------------------------
      // Validate asserted evidence
      // --------------------------------------------

      let issue =
        null;

      if (
        !rawSourceUrl
      ) {

        issue =
          `non-unknown value '${rawValue}' has no source_url`;

      } else if (
        !rawObservedText
      ) {

        issue =
          `non-unknown value '${rawValue}' has no observed_text`;

      } else if (
        !sourceDocumentMap.has(
          rawSourceUrl
        )
      ) {

        issue =
          "source_url was not supplied in this account's research packet";

      } else {

        const sourceDocument =
          sourceDocumentMap.get(
            rawSourceUrl
          );

        const quoteVerified =
          quoteExistsInSource(
            sourceDocument.content || "",
            rawObservedText
          );

        if (!quoteVerified) {

          issue =
            "observed_text could not be verified in the cited source";

        }
      }


      // --------------------------------------------
      // Absence claims
      // --------------------------------------------

      if (
        rawValue === "absent" &&
        !issue
      ) {

        /*
          We cannot algorithmically prove
          semantic negation.

          But absence claims must at least
          contain traceable source evidence.
        */

        if (
          !rawSourceUrl ||
          !rawObservedText
        ) {

          issue =
            "absent requires explicit source_url and observed_text";

        }
      }


      // --------------------------------------------
      // Fail closed at FIELD level
      // --------------------------------------------

      if (issue) {

        normalized =
          downgradeToUnknown(
            {
              value:
                rawValue,

              sourceUrl:
                rawSourceUrl,

              observedText:
                rawObservedText,

              reason:
                rawReason
            },

            issue
          );

        downgradedFields++;

        validationWarnings.push({
          account_id:
            parsed.account_id,

          company_name:
            parsed.company_name,

          evidence_key:
            key,

          original_value:
            rawValue,

          issue
        });
      }
    }


    // ----------------------------------------------
    // Resolve verified source
    // ----------------------------------------------

    let sourceDocument =
      null;

    if (
      normalized.sourceUrl
    ) {

      sourceDocument =
        sourceDocumentMap.get(
          normalized.sourceUrl
        ) || null;
    }


    // ----------------------------------------------
    // Build Supabase evidence row
    // ----------------------------------------------

    evidenceRows.push({
      account_id:
        parsed.account_id,

      evidence_type:
        "website_intelligence",

      evidence_key:
        key,

      evidence_value:
        normalized.value,

      evidence_json: {

        normalized_value:
          normalized.value,

        observed_text:
          normalized.observedText,

        reason:
          normalized.reason,

        validation_status:
          normalized.validationStatus,

        validation_issue:
          normalized.validationIssue,

        original_model_value:
          normalized.originalValue,

        original_source_url:
          normalized.originalSourceUrl,

        original_observed_text:
          normalized.originalObservedText,

        original_reason:
          normalized.originalReason,

        extraction_provider:
          "google_gemini",

        extraction_model:
          MODEL,

        research_version:
          RESEARCH_VERSION,

        packet_page_count:
          packet.page_count ||
          documents.length,

        packet_chars:
          packet.packet_chars ||
          null
      },

      source_type:
        "website",

      source_url:
        normalized.sourceUrl,

      source_provider:
        "company_website_via_apify",

      source_observed_at:
        sourceDocument
          ?.source_observed_at ||
        new Date()
          .toISOString(),

      confidence:
        normalized.confidence,

      is_positive:
        conceptPresent(
          normalized.value
        ),

      is_current:
        true,

      research_version:
        RESEARCH_VERSION,

      evidence_fingerprint:
        `${parsed.account_id}|${RESEARCH_VERSION}|${key}`
    });
  }


  // ------------------------------------------------
  // Account QA summary
  // ------------------------------------------------

  accountSummaries.push({
    account_id:
      parsed.account_id,

    company_name:
      parsed.company_name,

    evidence_rows:
      Object.keys(
        valueDomains
      ).length,

    downgraded_to_unknown:
      downgradedFields
  });
}


// --------------------------------------------------
// Final row-count validation
// --------------------------------------------------

const expectedEvidenceRows =
  accountSummaries.length *
  Object.keys(
    valueDomains
  ).length;

if (
  evidenceRows.length !==
  expectedEvidenceRows
) {
  throw new Error(
    `Evidence row count mismatch. ` +
    `Expected ${expectedEvidenceRows}, ` +
    `got ${evidenceRows.length}.`
  );
}


// --------------------------------------------------
// Return ONE aggregate object
// --------------------------------------------------

return [
  {
    json: {

      research_version:
        RESEARCH_VERSION,

      provider:
        "google_gemini",

      model:
        MODEL,

      accounts_researched:
        accountSummaries.length,

      evidence_dimensions:
        Object.keys(
          valueDomains
        ).length,

      evidence_count:
        evidenceRows.length,

      validation_warning_count:
        validationWarnings.length,

      accounts:
        accountSummaries,

      validation_warnings:
        validationWarnings,

      evidence_rows:
        evidenceRows
    }
  }
];
